import { canonicalSha256 } from '../core/canonical-json.mjs';
import { compileBudgetTree } from './budget-policy.mjs';
import { omissionEntry, finalizeOmissionManifest } from './omission-manifest.mjs';
import { createContextReceipt } from './context-receipt.mjs';

const CATEGORIES=['system','task','skills','code','artifacts','memory','toolOutput','references'];
function normalizeItem(value,index,category){if(typeof value==='string')return{id:`${category}-${index+1}`,text:value,priority:100-index};if(!value||typeof value!=='object')throw new TypeError(`Invalid ${category} context item`);return{id:String(value.id??`${category}-${index+1}`),text:String(value.text??value.content??''),priority:Number.isFinite(value.priority)?value.priority:50,sha256:value.sha256??null,retrieval:value.retrieval??null,required:value.required===true};}
async function prepare(model,registry,items,category){const result=[];for(let index=0;index<items.length;index++){const item=normalizeItem(items[index],index,category);const tokens=await registry.countText(model,item.text);result.push({...item,tokens,sha256:item.sha256??canonicalSha256({category,id:item.id,text:item.text})});}return result.sort((a,b)=>b.priority-a.priority||a.id.localeCompare(b.id));}
export async function compileGlobalContext({model,policy,tokenRegistry,inputs}){if(!tokenRegistry)throw new TypeError('tokenRegistry is required');const budget=compileBudgetTree(policy);const context={};const categories={};const omissions=[];for(const category of CATEGORIES){const candidates=await prepare(model,tokenRegistry,inputs?.[category]??[],category);const categoryBudget=budget.budgets[category]??0;let used=0;const included=[];for(const item of candidates){if(used+item.tokens<=categoryBudget){included.push(Object.freeze(item));used+=item.tokens;continue;}if(item.required)throw new RangeError(`Required context item ${item.id} exceeds ${category} budget`);omissions.push(omissionEntry({sourceId:item.id,category,reason:`${category} budget ${categoryBudget} exceeded`,estimatedTokens:item.tokens,retrieval:item.retrieval,sourceHash:item.sha256}));}context[category]=Object.freeze(included);categories[category]=used;}
 const totalInputTokens=Object.values(categories).reduce((sum,value)=>sum+value,0);if(totalInputTokens>budget.availableInput)throw new RangeError(`Compiled context ${totalInputTokens} exceeds available input ${budget.availableInput}`);const accounting=Object.freeze({categories:Object.freeze(categories),totalInputTokens,outputReserve:budget.outputReserve,safetyReserve:budget.safetyReserve,totalReserved:totalInputTokens+budget.outputReserve+budget.safetyReserve});const omissionManifest=finalizeOmissionManifest(omissions);const result={model,budget,context:Object.freeze(context),accounting,omissions:omissionManifest.entries,omissionManifest};const receipt=createContextReceipt(result);return Object.freeze({...result,contextReceipt:receipt,contextReceiptSha256:receipt.sha256});}
